import{z as A,x as d,o,c as E,q as s,j as n,D as l,d as t,s as i,S as p,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"抽象语法树","description":"","frontmatter":{"title":"抽象语法树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ast.md","filePath":"cs/ast.md","lastUpdated":1791063341000}'),m={name:"cs/ast.md"};function T(c,a,h,B,D,S){const r=d("Mermaid");return o(),E("div",null,[a[2]||(a[2]=s('<h1 id="抽象语法树" tabindex="-1">抽象语法树 <a class="header-anchor" href="#抽象语法树" aria-label="Permalink to &quot;抽象语法树&quot;">​</a></h1><div class="epigraph"><p>分析树忠实于产生式；抽象语法树只保留后课语义与翻译需要的运算节点。</p><footer>—— 据龙书第 5 章；Appel, Modern Compiler Implementation 整理</footer></div><p>上一课<a href="/cs/slr-lalr">SLR 与 LALR</a>在归约时已经能挂动作。本课不重造项集。缺口是：推导树含大量「只为文法分层」的节点（\\(E\\to T\\)、\\(T\\to F\\)）。后课类型检查与 IR 不需要它们。抽象语法树（AST）是压缩后的有序树：运算符、字面量、声明、语句列表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分析树的叶是记号，内节点是产生式。优先级分层会让 <code>1+2</code> 变成一长串单子节点。缺口是定义另一棵树：节点种类按语言概念（BinOp、If、Assign），孩子是子表达式，不再记得用了哪条 \\(E\\to E+T\\)。二义已在文法或冲突消解里去掉，AST 假定唯一。</p><p><a href="/cs/tree-as-acyclic">树作为无环连通图</a>给出树；本课指定节点载荷。不要把 AST 当 DAG：公共子表达式消除才把树收成 DAG，那是 IR 课以后。</p><p><span class="marginnote">给压缩一个数：<code>1+2</code> 的分析树因优先级分层（\\(E\\to T\\)、\\(T\\to F\\) 一路单链）要有十来个节点；AST 只剩 3 个——加、1、2。百万行程序里，这一刀砍掉的是前端一半以上的内存与遍历时间。</span></p><h3 id="抽象不是「不精确」" tabindex="-1">抽象不是「不精确」 <a class="header-anchor" href="#抽象不是「不精确」" aria-label="Permalink to &quot;抽象不是「不精确」&quot;">​</a></h3><p>丢掉的是语法糖与分层非终结符，不是类型信息——类型还没有。括号不进树：结合性已由结构表达。源位置（行号）应保留，为报错，那是装饰，不是抽象掉的对象。</p><p><span class="marginnote">龙书用语法制导定义把动作写在产生式上，直接 new 节点。Appel 强调 IR 前的 AST 是前端产品。本课不写访问者模式的全部样板。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>归约 \\(A\\to\\alpha\\) 时，用 \\(\\alpha\\) 各符号已有的子树构造 \\(A\\) 的 AST 节点。递归下降则每个 <code>parseA</code> 返回节点指针。关键字、分号通常不建节点。</p><p><span class="marginnote">直觉类比：归约时建 AST 像搭积木——每归约一条产生式，就把手头几块已搭好的子积木拼成更大一块；源程序读完时，手里那块就是整棵 AST。递归下降的 <code>parseA</code> 返回节点指针，是同一件事的自顶向下版本。</span></p>',13)),(o(),n(p,null,{default:l(()=>[i(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PARSE%5B%22%E5%88%86%E6%9E%90%E6%A0%91%20%2F%20%E5%BD%92%E7%BA%A6%22%5D%20--%3E%20DROP%5B%22%E4%B8%A2%E6%8E%89%E5%88%86%E5%B1%82%E4%B8%8E%E7%B3%96%22%5D%0A%20%20DROP%20--%3E%20AST%5B%22AST%22%5D%0A%20%20AST%20--%3E%20SEM%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%AC%A6%E5%8F%B7%E8%A1%A8%E4%B8%8E%E7%B1%BB%E5%9E%8B%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"列表结构（语句序列、参数表）用向量，不必强迫二叉。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"后课遍历 AST：作用域进入块节点、类型在表达式节点上综合。IR 生成是另一遍遍历。树形保持源程序的嵌套，便于报错；线性 IR 才方便数据流。本课不开始填类型。",-1)),a[6]||(a[6]=e("p",null,[t("树形怎么把优先级「记住」的？看 "),e("code",null,"1+2*3"),t("：乘法自然长在加法的更深处。")],-1)),(o(),n(p,null,{default:l(()=>[i(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADD%5B%22BinOp%20%E5%8A%A0%22%5D%20--%3E%20L1%5B%22%E5%AD%97%E9%9D%A2%E9%87%8F%201%22%5D%0A%20%20ADD%20--%3E%20MUL%5B%22BinOp%20%E4%B9%98%22%5D%0A%20%20MUL%20--%3E%20L2%5B%22%E5%AD%97%E9%9D%A2%E9%87%8F%202%22%5D%0A%20%20MUL%20--%3E%20L3%5B%22%E5%AD%97%E9%9D%A2%E9%87%8F%203%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p>宏展开若发生在词法/预处理，AST 可能看不见宏调用。那是语言设计，点名即可。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做类型检查、不建符号表、不生成三地址。不把 AST 序列化格式写成标准。具体语言的节点清单不穷尽。后课默认：语义分析的输入是 AST。名字如何对应声明是下一课作用域。</p><p><span class="marginnote">常见误区：初学者容易把 AST 画成 DAG，让相同的子表达式共享同一个节点。一旦共享，「树」的每个节点就可能有多个父亲，遍历会重复访问、析构会重复释放——共享是公共子表达式消除之后 IR 层的事，AST 保持严格树形。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AST 保留运算与语句结构，丢掉纯文法节点。</li><li>在归约或下降时构造；源位置留下报错。</li><li>还不是类型、不是 IR。</li><li>出处：Aho et al., 龙书第 5 章；Appel, <em>Modern Compiler Implementation</em>。</li></ul>',6))])}const _=A(m,[["render",T]]);export{f as __pageData,_ as default};
